const group = document.querySelector('[role="radiogroup"]');
const cs = getComputedStyle(group);
const chips = [...group.children];
const rects = chips.map(c => c.getBoundingClientRect());
JSON.stringify({
  display: cs.display,
  gap: cs.gap,
  justifyContent: cs.justifyContent,
  groupWidth: group.getBoundingClientRect().width,
  chipCount: chips.length,
  chipRects: rects.map(r => ({x: Math.round(r.x), w: Math.round(r.width)})),
}, null, 1);

const group = document.querySelector('[role="radiogroup"]');
const content = document.querySelector('[data-card-slot="content"]');
const sizeChipsWrapper = document.querySelector('[data-card-slot="sizeChips"]');
JSON.stringify({
  groupWidth: group.getBoundingClientRect().width,
  groupCSSWidth: getComputedStyle(group).width,
  wrapperWidth: sizeChipsWrapper.getBoundingClientRect().width,
  wrapperCSSWidth: getComputedStyle(sizeChipsWrapper).display,
  contentWidth: content.getBoundingClientRect().width,
  contentPaddingLeft: getComputedStyle(content).paddingLeft,
  contentPaddingRight: getComputedStyle(content).paddingRight,
});

const sizeChipsWrapper = document.querySelector('[data-card-slot="sizeChips"]');
const priceEl = document.querySelector('[data-card-slot="price"]');
const radiogroup = document.querySelector('[role="radiogroup"]');
JSON.stringify({
  sizeChipsWrapperExists: !!sizeChipsWrapper,
  sizeChipsWrapperDisplay: sizeChipsWrapper ? getComputedStyle(sizeChipsWrapper).display : null,
  sizeChipsWrapperHTML: sizeChipsWrapper ? sizeChipsWrapper.innerHTML.slice(0, 200) : null,
  priceDisplay: priceEl ? getComputedStyle(priceEl).display : null,
  radiogroupExists: !!radiogroup,
});

